// SEARCH PLAN – what the agent looks for each run.
// Edit this list to change searches. Reed = UK job board (needs the "Reed API" credential).
// Remotive = free remote-jobs API (no key; please keep to a few calls per day).
// LEARN FROM MY FEEDBACK (statuses I set in the Job Tracker)
// - a company I skipped 2+ times and never applied to is blocked
// - a search category where I skipped 8+ jobs and applied to none is paused
// (at least one category always stays active)
const POS = ["applied", "interview", "offer"];
const byCompany = {}, byCat = {};
for (const r of $("Read My Feedback").all().map((i) => i.json).filter((r) => r.job_id)) {
  const s = String(r.status || "new").toLowerCase();
  if (!POS.includes(s) && s !== "skipped") continue;
  const c = String(r.company || "").trim().toLowerCase();
  const cat = r.search_category || "";
  byCompany[c] = byCompany[c] || { pos: 0, skip: 0 };
  byCat[cat] = byCat[cat] || { pos: 0, skip: 0 };
  const k = POS.includes(s) ? "pos" : "skip";
  byCompany[c][k]++; byCat[cat][k]++;
}
const blocked_companies = Object.entries(byCompany).filter(([c, v]) => c && v.skip >= 2 && v.pos === 0).map(([c]) => c);
let paused_categories = Object.entries(byCat).filter(([c, v]) => c && v.pos === 0 && v.skip >= 8).map(([c]) => c);

const reed = [
  { category: "Graduate AI & data", keywords: "artificial intelligence", graduate: true },
  { category: "Graduate AI & data", keywords: "machine learning", graduate: true },
  { category: "Graduate AI & data", keywords: "junior data analyst" },
  { category: "Graduate AI & data", keywords: "AI automation" },
  { category: "Part-time IT", keywords: "IT support", partTime: true, locationName: "London", distanceFromLocation: 25 },
  { category: "Internship", keywords: "data internship" },
  { category: "Internship", keywords: "AI internship" }
];
const remotive = [
  { category: "Remote AI & data", query: "search=machine%20learning" },
  { category: "Remote AI & data", query: "category=data" }
];

const allCats = [...new Set([...reed, ...remotive].map((s) => s.category))];
if (allCats.every((c) => paused_categories.includes(c))) paused_categories = [];
const active = (s) => !paused_categories.includes(s.category);
const feedback_note = [
  blocked_companies.length ? `blocked ${blocked_companies.length} skipped compan${blocked_companies.length > 1 ? "ies" : "y"}` : "",
  paused_categories.length ? `paused: ${paused_categories.join(", ")}` : ""
].filter(Boolean).join("; ");

const started_at = Date.now(); // used by the run log to measure how long a run takes

const qs = (o) => Object.entries(o)
  .filter(([k, v]) => k !== "category" && v !== undefined)
  .map(([k, v]) => `${k}=${encodeURIComponent(v)}`)
  .join("&");

return [
  ...reed.filter(active).map((s) => ({ json: {
    source: "reed",
    started_at, blocked_companies, paused_categories, feedback_note,
    category: s.category,
    label: s.keywords,
    url: `https://www.reed.co.uk/api/1.0/search?${qs(s)}&resultsToTake=25`
  } })),
  ...remotive.filter(active).map((s) => ({ json: {
    source: "remotive",
    started_at, blocked_companies, paused_categories, feedback_note,
    category: s.category,
    label: s.query,
    url: `https://remotive.com/api/remote-jobs?${s.query}&limit=25`
  } }))
];

// NORMALISE & FILTER
// Turns Reed and Remotive results into one clean list of jobs:
// - same fields for every job, HTML removed
// - only jobs posted in the last 14 days
// - senior / manager roles removed (targeting graduate & junior roles)
// - Remotive jobs kept only if open to UK / Europe / worldwide applicants
// - job title must be AI / data / tech related (keyword searches also return
//   unrelated ads, e.g. sales or healthcare; this saves AI calls)
// - companies I keep skipping are removed (see Search Plan)
// - duplicates removed (same job id, or same title + company)
const DAYS = 14;
const cutoff = Date.now() - DAYS * 24 * 60 * 60 * 1000;
const SENIOR = /\b(senior|snr|sr\.?|lead|principal|head of|manager|director|staff engineer|architect|vp)\b/i;
const RELEVANT = /\b(ai|artificial intelligence|machine learning|ml|llm|nlp|data|analyst|analytics|python|automation|software|developer|engineer|it|ict|tech|technology|technical|technician|digital|computer|cloud|helpdesk|help desk|service desk|desktop|network|systems|cyber)\b/i;
const OPEN_TO_UK = /(\buk\b|united kingdom|england|europe|emea|worldwide|anywhere|global)/i;

const strip = (html) => String(html || "")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
  .replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, " ").trim();

const ukDate = (s) => { // Reed dates look like 28/10/2026
  const m = String(s || "").match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  return m ? new Date(`${m[3]}-${m[2]}-${m[1]}T00:00:00Z`) : null;
};
const money = (min, max) => {
  if (!min && !max) return "";
  const f = (n) => "£" + Math.round(n).toLocaleString("en-GB");
  return min && max && min !== max ? `${f(min)}–${f(max)}` : f(min || max);
};

const jobs = [];
const problems = [];
const items = $input.all();

items.forEach((item, i) => {
  let plan = {};
  try { plan = $("Search Plan").itemMatching(i).json; } catch (e) { /* pairing not available */ }
  const r = item.json;

  if (r.error) {
    problems.push(`${plan.source || "source"} search "${plan.label || "?"}" failed: ${String(r.error.message || r.error).slice(0, 150)}`);
    return;
  }

  if (Array.isArray(r.results)) { // Reed
    for (const j of r.results) {
      const posted = ukDate(j.date);
      jobs.push({
        job_id: `reed-${j.jobId}`,
        source: "Reed",
        search_category: plan.category || "",
        title: strip(j.jobTitle),
        company: strip(j.employerName),
        location: strip(j.locationName),
        salary: money(j.minimumSalary, j.maximumSalary),
        url: j.jobUrl || `https://www.reed.co.uk/jobs/${j.jobId}`,
        posted: posted ? posted.toISOString().slice(0, 10) : "",
        postedMs: posted ? posted.getTime() : Date.now(),
        snippet: strip(j.jobDescription).slice(0, 1500)
      });
    }
  } else if (Array.isArray(r.jobs)) { // Remotive
    for (const j of r.jobs) {
      if (!OPEN_TO_UK.test(j.candidate_required_location || "")) continue;
      const posted = new Date(j.publication_date);
      jobs.push({
        job_id: `remotive-${j.id}`,
        source: "Remotive",
        search_category: plan.category || "",
        title: strip(j.title),
        company: strip(j.company_name),
        location: `Remote (${strip(j.candidate_required_location)})`,
        salary: strip(j.salary),
        url: j.url,
        posted: isNaN(posted) ? "" : posted.toISOString().slice(0, 10),
        postedMs: isNaN(posted) ? Date.now() : posted.getTime(),
        snippet: strip(j.description).slice(0, 1500)
      });
    }
  }
});

const blocked = new Set(($("Search Plan").first().json.blocked_companies || []).map((c) => String(c).toLowerCase()));
const seen = new Set();
const clean = jobs
  .filter((j) => j.postedMs >= cutoff)
  .filter((j) => !SENIOR.test(j.title))
  .filter((j) => RELEVANT.test(j.title))
  .filter((j) => !blocked.has(String(j.company).trim().toLowerCase()))
  .sort((a, b) => b.postedMs - a.postedMs)
  .filter((j) => {
    const k1 = j.job_id;
    const k2 = (j.title + "|" + j.company).toLowerCase().replace(/\s+/g, " ");
    if (seen.has(k1) || seen.has(k2)) return false;
    seen.add(k1); seen.add(k2);
    return true;
  })
  .map(({ postedMs, ...j }) => j);

if (problems.length) console.log("Search problems:", problems);
return clean.map((j) => ({ json: j }));

// SCORE MATCHES
// The AI only rates each requirement. The match score is calculated HERE, in code:
// - essential requirement = weight 2, desirable = weight 1
// - met = full credit, partial = half, not evidenced = none
// - every evidence quote is searched for in the CV: not found = half credit (possible hallucination)
// - "met" with no quote gets no credit
// - minus 10 if the ad asks for 2 years' experience, minus 20 for 3+ years, minus 35 for a senior role
// - minus 20 if the minimum salary is £60k+ (these roles almost always need years of experience)
// - code double-checks for paid-training / "no experience needed" recruiter schemes (the AI can miss them)
// Then the top 3 good matches (score 55+, no red flags) are marked for a tailored CV + cover letter.
const norm = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9+#%.]+/g, " ").trim();
const LABEL = {
  paid_course_or_training_fee: "⚠️ Possible paid course / training scheme",
  citizenship_or_clearance_required: "⚠️ Needs citizenship or security clearance",
  senior_level: "Senior level",
  full_time_hours: "Full-time hours",
  not_uk_eligible: "⚠️ Not open to UK",
  too_little_information: "Short advert – check the full ad"
};
const COURSE = /no experience (is )?(needed|required|necessary)|we('| wi)ll train you|fully funded training|funded course|career chang|traineeship|course fee|training provider|get (you )?certified|kick-?start your career in/i;
const RED = ["paid_course_or_training_fee", "citizenship_or_clearance_required", "not_uk_eligible"];

const scored = [];
const failed = [];
$input.all().forEach((item, i) => {
  const job = $("Build Match Requests").itemMatching(i).json;
  const cv = norm(job.cv_text);
  let r;
  try {
    r = JSON.parse(item.json.choices[0].message.content);
    if (!Array.isArray(r.job_requirements) || !r.job_requirements.length) throw new Error("no requirements returned");
  } catch (e) {
    // Not saved, so the job is tried again on the next run.
    failed.push(`${job.title} (${job.company}): ${String(item.json.error?.message || e.message).slice(0, 150)}`);
    return;
  }

  let got = 0, max = 0, unverified = 0;
  const met = [], partial = [], notShown = [];
  for (const q of r.job_requirements) {
    const w = q.importance === "essential" ? 2 : 1;
    max += w;
    let c = q.status === "met" ? 1 : q.status === "partial" ? 0.5 : 0;
    const ev = norm(q.evidence);
    if (c > 0 && !ev) c = 0;
    else if (c > 0 && !cv.includes(ev)) { c /= 2; unverified++; }
    got += w * c;
    (q.status === "met" ? met : q.status === "partial" ? partial : notShown).push(q.requirement);
  }
  const yrs = r.experience_years_required || 0;
  const flags = [...new Set(r.flags || [])];
  const text = job.title + " " + job.snippet;
  // v4 (from the accuracy test): any "trainee" title from a recruiter / training company is treated as a possible paid scheme
  const recruiterTrainee = /\btrainee\b/i.test(job.title) && /recruit|training|academy|career/i.test(job.company);
  // v4: sales / recruitment roles are not technical roles, whatever the AI rating says
  const offTarget = /\b(recruitment consultant|recruiter|sales (executive|consultant|representative|manager)|business development)\b/i.test(job.title);
  if ((COURSE.test(text) || recruiterTrainee) && !flags.includes("paid_course_or_training_fee")) flags.push("paid_course_or_training_fee");
  let penalty = yrs >= 3 ? 20 : yrs === 2 ? 10 : 0;
  if (flags.includes("senior_level")) penalty = Math.max(penalty, 35);
  const minSalary = Number(String(job.salary || "").replace(/,/g, "").match(/£(\d+)/)?.[1] || 0);
  const highSalary = minSalary >= 60000;
  if (highSalary) penalty += 20;
  const score = Math.max(0, Math.min(100, Math.round((100 * got) / max - penalty)));
  const red = flags.some((f) => RED.includes(f));
  // v4: senior and non-technical roles can never be better than Weak
  const fit = red ? "Red flag" : (flags.includes("senior_level") || offTarget) ? "Weak" : score >= 70 ? "Strong" : score >= 45 ? "Possible" : "Weak";

  const flagText = flags.map((f) => LABEL[f] || f);
  if (highSalary) flagText.push("High salary – usually needs years of experience");
  if (yrs > 0) flagText.push(`Asks for ${yrs}+ years' experience`);
  if (offTarget) flagText.push("Not a technical role");
  if (unverified) flagText.push(`${unverified} AI quote(s) not found in CV (half credit)`);

  scored.push({
    job_id: job.job_id, title: job.title, company: job.company, location: job.location, salary: job.salary,
    source: job.source, search_category: job.search_category, url: job.url, posted: job.posted,
    snippet: job.snippet,
    match_score: score, fit,
    why_fit: [r.why_fit, met.length ? "Met: " + met.join(", ") : "", partial.length ? "Partly: " + partial.join(", ") : ""].filter(Boolean).join(" | ").slice(0, 1500),
    missing: [r.missing, notShown.length ? "Not shown in CV: " + notShown.join(", ") : ""].filter(Boolean).join(" | ").slice(0, 1000),
    flags: flagText.join("; "),
    status: "new", cover_letter: "", tailored_cv: "", tailor: false, red
  });
});

scored.sort((a, b) => b.match_score - a.match_score);
scored.filter((j) => j.match_score >= 55 && !j.red && j.fit !== "Weak").slice(0, 3).forEach((j) => { j.tailor = true; });
if (failed.length) console.log("Not scored this run (will retry next run):", failed);
return scored.map(({ red, ...j }) => ({ json: j }));

// BUILD TAILORING REQUESTS
// Only for the top matches: asks Groq for a tailored CV summary, skills order,
// reworded project bullets, ATS keywords and a cover letter, using CV facts only.
const CV = $("Build Match Requests").first().json.cv_text;
const SYSTEM = "You help a candidate tailor her CV and write a cover letter for ONE job advert, so it passes ATS keyword screening AND stays 100% truthful. Fill every field.

STRICT HONESTY RULES:
- Use ONLY facts written in the CV. Never add skills, tools, employers, years of experience, grades, results or achievements that are not in the CV.
- You MAY reorder, shorten and reword CV content, and use the advert's own wording when it describes the same thing the CV shows (for example, the CV says "REST APIs" and the advert says "API integration").
- If the advert asks for something the CV does not show, put it in ats_keywords_missing. Never put it anywhere else.

Fields:
- tailored_summary: 2 or 3 sentences (max 60 words) for the top of the CV, aimed at this job, using only CV facts. Write in standard CV style without 'I', 'my' or 'me' (for example: 'MSc Artificial Intelligence student who builds ...'). Do not name the company or the recruiter. Avoid filler words such as passionate, eager or hard-working. Never claim abilities the CV does not show, such as 'proven ability', production deployment, stakeholder work or translating business requirements.
- top_skills: 8 to 12 skills copied exactly as written in the CV, most relevant to this advert first.
- highlight_bullets: 3 or 4 project bullets from the CV, reworded to match the advert's language, with no new facts.
- ats_keywords_matched: keywords from the advert that the CV genuinely shows.
- ats_keywords_missing: keywords from the advert that the CV does not show.
- cover_letter: 170 to 230 words. Start with "Dear Hiring Manager,". Mention the job title and company. Use 2 or 3 specific CV facts that match the advert. Friendly, professional UK English. Do not mention visa status. Do NOT write a sign-off or name at the end; it is added automatically.
";
const SCHEMA = {"type":"object","additionalProperties":false,"required":["tailored_summary","top_skills","highlight_bullets","ats_keywords_matched","ats_keywords_missing","cover_letter"],"properties":{"tailored_summary":{"type":"string"},"top_skills":{"type":"array","items":{"type":"string"}},"highlight_bullets":{"type":"array","items":{"type":"string"}},"ats_keywords_matched":{"type":"array","items":{"type":"string"}},"ats_keywords_missing":{"type":"array","items":{"type":"string"}},"cover_letter":{"type":"string"}}};

return $input.all().map((item) => {
  const j = item.json;
  const user = "JOB TITLE: " + j.title + "
COMPANY: " + j.company + "
LOCATION: " + j.location +
    "

JOB ADVERT (may be shortened):
" + j.snippet + "

CANDIDATE CV:
" + CV;
  return { json: { ...j, groqBody: {
    model: "openai/gpt-oss-20b", temperature: 0.3, seed: 42, reasoning_effort: "low", max_completion_tokens: 4000,
    response_format: { type: "json_schema", json_schema: { name: "cv_tailoring", strict: true, schema: SCHEMA } },
    messages: [{ role: "system", content: SYSTEM }, { role: "user", content: user }]
  } } };
});

// BUILD TAILORED CV & COVER LETTER
// Safety checks in code:
// - every "top skill" must appear in my real CV, otherwise it is removed (no invented skills)
// - any email address the AI writes is removed; my real contact details are added by code
const norm = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9+#%.]+/g, " ").trim();
const CV = norm($("Build Match Requests").first().json.cv_text);
const SIGN_OFF = "\n\nKind regards,\nYour Name\you@example.com | linkedin.com/in/your-profile | github.com/your-username";

return $input.all().map((item, i) => {
  const job = $("Build Tailoring Requests").itemMatching(i).json;
  const { groqBody, snippet, tailor, ...row } = job;
  let t;
  try { t = JSON.parse(item.json.choices[0].message.content); }
  catch (e) {
    return { json: { ...row, flags: [row.flags, "Tailoring failed: " + String(item.json.error?.message || e.message).slice(0, 120)].filter(Boolean).join("; ") } };
  }
  const skills = (t.top_skills || []).filter((s) => CV.includes(norm(s)));
  const dropped = (t.top_skills || []).filter((s) => !CV.includes(norm(s)));
  const tailored = [
    "PROFESSIONAL SUMMARY (tailored)",
    t.tailored_summary,
    "",
    "KEY SKILLS (put these first)",
    skills.join(" · "),
    "",
    "PROJECT BULLETS TO USE",
    ...(t.highlight_bullets || []).map((b) => "- " + b),
    "",
    "ATS KEYWORDS YOU GENUINELY MATCH: " + (t.ats_keywords_matched || []).join(", "),
    "IN THE AD BUT NOT IN YOUR CV (do NOT add unless true): " + (t.ats_keywords_missing || []).join(", "),
    dropped.length ? "Removed by safety check (not in your CV): " + dropped.join(", ") : ""
  ].join("\n").trim();
  const letter = String(t.cover_letter || "").replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, "").trim() + SIGN_OFF;
  return { json: { ...row, tailored_cv: tailored, cover_letter: letter } };
});

// PREPARE ROW – keeps only the Job Tracker columns
const COLS = ["job_id", "title", "company", "location", "salary", "source", "search_category", "url", "posted",
  "match_score", "fit", "why_fit", "missing", "flags", "tailored_cv", "cover_letter", "status"];
return $input.all().map((item) => ({ json: Object.fromEntries(COLS.map((c) => [c, item.json[c] ?? (c === "match_score" ? 0 : "")])) }));

// ADD FULL ADVERT
// Reed's search only returns a short preview of each advert. This swaps it for the
// full advert from Reed's job-details API (when that call worked), plus contract details,
// so the AI scores the real requirements instead of a teaser.
const strip = (html) => String(html || "")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
  .replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"')
  .replace(/\s+/g, " ").trim();

return $input.all().map((item, i) => {
  const job = $("Max 10 New Jobs").itemMatching(i).json;
  const d = item.json;
  if (d.error || !d.jobDescription) return { json: { ...job, full_advert: false } };
  const extra = [
    d.contractType ? "Contract: " + d.contractType : "",
    d.fullTime ? "Full-time" : "",
    d.partTime ? "Part-time" : "",
    d.expirationDate ? "Closes: " + d.expirationDate : ""
  ].filter(Boolean).join(" | ");
  return { json: { ...job, snippet: (extra ? extra + "\n" : "") + strip(d.jobDescription).slice(0, 4000), full_advert: true } };
});

// WRITE RUN LOG – one row per run, so you can see the agent is healthy
// (jobs found, AI calls, failures, tokens used, time taken).
const safe = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const started = $("Search Plan").first().json.started_at;
const rows = safe("Prepare Row").map((i) => i.json);
const sent = safe("Build Match Requests").length;
const scored = safe("Score Matches").length;
const tokens = [...safe("Ask Groq: Match"), ...safe("Ask Groq: Tailor")]
  .reduce((sum, i) => sum + (i.json.usage?.total_tokens || 0), 0);
const searchErrors = [...safe("Search Reed"), ...safe("Search Remotive")].filter((i) => i.json.error).length;
const advertErrors = safe("Add Full Advert").filter((i) => !i.json.full_advert).length;
const tailorFailed = rows.filter((r) => /Tailoring failed/.test(r.flags)).length;
const notes = [
  $("Search Plan").first().json.feedback_note ? "learned from feedback: " + $("Search Plan").first().json.feedback_note : "",
  searchErrors ? `${searchErrors} search call(s) failed` : "",
  advertErrors ? `${advertErrors} full advert(s) not available, preview used` : "",
  sent - scored ? `${sent - scored} job(s) not scored, will retry next run` : "",
  tailorFailed ? `${tailorFailed} tailoring call(s) failed` : ""
].filter(Boolean).join("; ");

return [{ json: {
  run_at: new Date().toLocaleString("en-GB", { timeZone: "Europe/London" }),
  trigger: $execution.mode,
  status: notes ? "OK with warnings" : "OK",
  jobs_found: safe("Normalise & Filter").length,
  new_jobs: safe("Skip Jobs Already Seen").length,
  full_adverts: safe("Add Full Advert").filter((i) => i.json.full_advert).length,
  ai_scored: scored,
  ai_failed: sent - scored,
  strong_matches: rows.filter((r) => r.fit === "Strong").length,
  red_flags: rows.filter((r) => r.fit === "Red flag").length,
  tailored: rows.filter((r) => r.tailored_cv).length,
  ai_tokens: tokens,
  duration_sec: Math.round((Date.now() - started) / 1000),
  notes
} }];
